<?php
namespace App\Actions;use App\Models\Order;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TransitionOrderAction{private const MAP=['PENDING'=>['ACCEPTED','CANCELLED','REJECTED'],'ACCEPTED'=>['PREPARING','CANCELLED'],'PREPARING'=>['READY','CANCELLED'],'READY'=>['DELIVERED'],'DELIVERED'=>[],'CANCELLED'=>[],'REJECTED'=>[]];public function execute(Order $o,string $to,?int $userId=null,?string $note=null):Order{return DB::transaction(function()use($o,$to,$userId,$note){$o->refresh();$from=$o->status;if(!in_array($to,self::MAP[$from]??[],true))throw ValidationException::withMessages(['status'=>"Invalid transition {$from} → {$to}."]);$changes=['status'=>$to];if($to==='ACCEPTED')$changes['accepted_at']=now();if($to==='READY')$changes['ready_at']=now();if($to==='DELIVERED')$changes['delivered_at']=now();$o->update($changes);DB::table('order_status_history')->insert(['hotel_id'=>$o->hotel_id,'order_id'=>$o->id,'changed_by'=>$userId,'from_status'=>$from,'to_status'=>$to,'note'=>$note,'created_at'=>now()]);return $o->fresh();});}}
